"""Exact conformance/falsification controls. Counts are not independent worlds.

Arbitrary wealth tables in algebra tests are NOT statistical data. Probability
controls separately use explicitly specified conditional measurement laws.
"""
from fractions import Fraction as Q
from itertools import product
from random import Random
from copy import deepcopy
from dataclasses import replace
import json
import fixtures as f
from graph_model import parse, compile_model, solve, rat, digest
from graph_audit import GraphAudit, replay
from verify_graph import check_certificate


def need(ok, label):
    if not ok:
        raise AssertionError(label)


def explicit_paths(model, wealth, alpha):
    """Independent corner-bound compiler and recursive full path enumeration.

    Only small box models. Affine extrema over a box occur at corners, so this
    checks the production coefficient-sign calculation by a different route.
    """
    corners=list(product(*[(l,u) for l,u in model.box]))
    by={n.name:n for n in model.nodes}
    values={}
    for node in model.nodes:
        tables=[[a.c+sum((v*x for v,x in zip(a.v,t)),Q(0)) for a in node.actions] for t in corners]
        for i,a in enumerate(node.actions):
            rows=[]; blocked=False
            for j,b in enumerate(node.actions):
                if i==j: continue
                contrasts=[scores[j]-scores[i] for scores in tables]
                if min(contrasts)>model.eta: blocked=True
                if min(contrasts)<=model.eta<max(contrasts):
                    rows.append(node.name+'/'+a.name+'/'+b.name)
            if not blocked:
                values[node.name,a.name]=sum((wealth[j] for j in rows),Q(0))/len(rows) if rows else Q(1)
    out=[]
    def walk(h, path, residual):
        for a in by[h].actions:
            if (h,a.name) not in values: continue
            total=residual+values[h,a.name]-1/alpha
            bad=(a.bit==0 and model.target in ('A','AB')) or (not a.keep and model.target in ('B','AB'))
            if bad:
                out.append((path+[(h,a.name,None)],total))
            else:
                for s in a.next: walk(s,path+[(h,a.name,s)],total)
    walk(model.root,[],Q(0))
    return out


def actual_paths(model, theta):
    by={n.name:n for n in model.nodes}; out=[]
    def walk(h,path):
        actions=by[h].actions
        if not actions: return
        scores=[a.c+sum((x*v for x,v in zip(theta,a.v)),Q(0)) for a in actions]
        for a,score in zip(actions,scores):
            if max(scores)-score>model.eta: continue
            bad=(a.bit==0 and model.target in ('A','AB')) or (not a.keep and model.target in ('B','AB'))
            if bad: out.append(tuple(path+[(h,a.name,None)]))
            else:
                for s in a.next: walk(s,path+[(h,a.name,s)])
    walk(model.root,[])
    return out


def generated():
    rng=Random(30666)
    for case in range(72):
        dim=case%3
        size=2+case%4
        nodes=[]
        for i in range(size):
            acts=[]
            for b in range(2+(case+i)%2):
                for bit in (0,1):
                    nxt=[]
                    if i+1<size and rng.randrange(3):
                        nxt=[j for j in range(i+1,size) if rng.randrange(2)]
                    acts.append(f.action('a'+str(b)+str(bit),'b'+str(b),bit,b!=1,
                                Q(rng.randrange(-4,5),2),[Q(rng.randrange(-3,4),2) for _ in range(dim)],
                                ['h'+str(j) for j in nxt]))
            nodes.append(dict(name='h'+str(i),actions=acts))
        raw=dict(root='h0',target='B',eta=str((Q(0),Q(1,4),Q(1))[case%3]),
                 box=[['0','1']]*dim,nodes=nodes)
        for target in ('A','B','AB'):
            item=deepcopy(raw); item['target']=target
            yield item


def algebra():
    rng=Random(3066601)
    models=snapshots=paths=actual=0
    totals={'pass':0,'not_certified':0}
    fixed=[f.single(),f.fork(),f.rejecting_prefix(),f.long_chain(4),f.zero_threshold(),f.latent_reachability()]
    for raw in fixed+list(generated()):
        model=parse(raw); g=compile_model(model); models+=1
        for trial in range(4):
            wealth={r.name:Q(rng.choice((0,1,4,16,64,256)),rng.choice((1,1,2))) for r in g.rows}
            report=solve(g,wealth,Q(1,16))
            listed=explicit_paths(model,wealth,Q(1,16))
            expected=min((v for p,v in listed),default=None)
            need(report['root_residual']==expected,'Bellman residual mismatch')
            need(report['first_bad_paths']==len(listed),'Path coverage/count mismatch')
            want=expected is None or expected>=0
            need(report['current_pass']==want,'Path mean predicate mismatch')
            checked=check_certificate(model,wealth,Q(1,16),report['certificate'])
            need(checked['valid']==want,'Local certificate checker mismatch')
            if report['unresolved_path']:
                w=tuple(tuple(x) for x in report['unresolved_path'])
                need(any(tuple(p)==w and val<0 for p,val in listed),'Invalid unresolved witness')
            totals['pass' if want else 'not_certified']+=1
            snapshots+=1; paths+=len(listed)
            if trial==0:
                syntax={tuple(p) for p,v in listed}
                for theta in product((Q(0),Q(1,2),Q(1)),repeat=len(model.box)):
                    reached=actual_paths(model,theta)
                    need(all(p in syntax for p in reached),'Compiler lost a genuine bad path')
                    actual+=len(reached)
    return dict(models=models,wealth_snapshots=snapshots,enumerated_path_instances=paths,
                actual_bad_path_instances=actual,verdicts=totals)


