"""Local Bellman certificate check, with comparison compilation redone here.

No shortest-path search or production comparison helper is called. The frozen
schema, interval model, hashing convention and theory remain shared. This is not
an independently operated review or a verifier of measurement authenticity.
"""
from fractions import Fraction as Q
from dataclasses import asdict
from graph_model import rat, digest, parse


def check_certificate(model, wealth, alpha, cert):
    """Check a sufficient lower-bound certificate for ALL graph paths."""
    try:
        model = parse(asdict(model))  # Revalidate domain and complete paired schema.
        alpha = rat(alpha)
        if not 0 < alpha < 1 or cert['model_hash'] != model.hash or rat(cert['alpha']) != alpha:
            raise ValueError('Model/alpha binding')
        observed = {j: rat(x) for j, x in wealth.items()}
        if any(x < 0 for x in observed.values()):
            raise ValueError('Negative evidence')
        if cert['evidence_hash'] != digest({j: str(x) for j, x in observed.items()}):
            raise ValueError('Evidence binding')
        potential = {h: None if x is None else rat(x) for h, x in cert['lower'].items()}
        if set(potential) != {n.name for n in model.nodes}:
            raise ValueError('Incomplete node certificate')
        expected, action_e = set(), {}
        for node in model.nodes:
            for selected in node.actions:
                used, impossible = [], False
                for competitor in node.actions:
                    if competitor.name == selected.name:
                        continue
                    lower = upper = competitor.c-selected.c
                    for j in range(len(model.box)):
                        coefficient = competitor.v[j]-selected.v[j]
                        left, right = model.box[j]
                        lower += coefficient*(left if coefficient >= 0 else right)
                        upper += coefficient*(right if coefficient >= 0 else left)
                    if lower > model.eta:
                        impossible = True
                    elif upper > model.eta:
                        used.append(node.name+'/'+selected.name+'/'+competitor.name)
                if impossible:
                    continue
                expected.update(used)
                action_e[node.name, selected.name] = sum((observed[j] for j in used), Q(0))/len(used) if used else Q(1)
        if set(observed) != expected:
            raise ValueError('Incorrect full comparison set')
        checks = 0
        for node in model.nodes:
            for action in node.actions:
                key = (node.name, action.name)
                if key not in action_e:
                    continue
                immediate_bad = ((model.target != 'B' and action.bit == 0)
                                 or (model.target != 'A' and not action.keep))
                # No optimizer: verify every original edge inequality.
                tails = [Q(0)] if immediate_bad else [potential[s] for s in action.next]
                for tail in tails:
                    if tail is None:
                        continue
                    checks += 1
                    lhs = potential[node.name]
                    rhs = action_e[key]-1/alpha+tail
                    if lhs is None or lhs > rhs:
                        raise ValueError('Unjustified lower bound/infinity at '+node.name)
        root_bound = potential[model.root]
        if root_bound is not None and root_bound < 0:
            raise ValueError('Root bound does not certify all paths')
        return {'valid': True, 'inequalities': checks}
    except (ValueError, TypeError, KeyError, ZeroDivisionError) as exc:
        return {'valid': False, 'reason': str(exc)}
