def bad(a, target):
    return (target in ('A', 'AB') and a.bit == 0) or (target in ('B', 'AB') and not a.keep)


def compile_model(m, max_rows=1000000):
    order = topology(m)
    rows, terms, blocked = [], [], []
    by = {n.name: n for n in m.nodes}
    for n in m.nodes:
        for a in n.actions:
            candidates, exclusions = [], []
            for other in n.actions:
                if other.name == a.name:
                    continue
                offset = other.c-a.c
                vec = tuple(x-y for x, y in zip(other.v, a.v))
                lo = offset+sum((min(x*l, x*u) for x, (l, u) in zip(vec, m.box)), Q(0))
                hi = offset+sum((max(x*l, x*u) for x, (l, u) in zip(vec, m.box)), Q(0))
                name = '/'.join((n.name, a.name, other.name))
                if lo > m.eta:
                    exclusions.append(name)
                elif hi > m.eta:
                    candidates.append(Row(name, offset, vec, lo, hi, (m.eta-lo)/(hi-lo)))
            key = (n.name, a.name)
            if exclusions:
                blocked.append((key, exclusions[0]))
            else:
                rows.extend(candidates)
                terms.append((key, tuple(r.name for r in candidates)))
            if len(rows) > max_rows:
                raise ValueError('Comparison resource limit')
    height = {}
    for h in reversed(order):
        height[h] = max((1+max((height[s] for s in a.next), default=0)
                         for a in by[h].actions), default=0)
    return Compiled(m, order, tuple(rows), tuple(terms), tuple(blocked),
                    height[m.root], max((len(t) for k, t in terms), default=0))


def action_values(g, wealth):
    if set(wealth) != {r.name for r in g.rows}:
        raise ValueError('Incomplete or extra comparison evidence')
    w = {j: rat(x) for j, x in wealth.items()}
    if any(x < 0 for x in w.values()):
        raise ValueError('Negative e-process value')
    return {key: sum((w[j] for j in terms), Q(0))/len(terms) if terms else Q(1)
            for key, terms in g.terms}


def solve(g, wealth, alpha):
    """Minimum additive residual; None means +infinity/no first-bad path.

    This is a graph obligation, NOT a feasible-parameter counterexample search.
    A negative path may combine parameter-incompatible comparisons.
    """
    alpha = rat(alpha)
    if not 0 < alpha < 1:
        raise ValueError('Invalid alpha')
    threshold = 1/alpha
    values = action_values(g, wealth)
    by = {n.name: n for n in g.model.nodes}
    distance, choices, counts = {}, {}, {}
    operations = 0
    for h in reversed(g.order):
        best, choice, count = None, None, 0
        for a in by[h].actions:
            if (h, a.name) not in values:
                continue  # Strict box-dominance proof generated by compiler.
            cost = values[h, a.name]-threshold
            if bad(a, g.model.target):
                candidates = [(cost, None)]
                count += 1
            else:
                candidates = [(cost+distance[s], s) for s in a.next if distance[s] is not None]
                count += sum(counts[s] for s in a.next)
            for value, successor in candidates:
                operations += 1
                if best is None or value < best:
                    best, choice = value, (a.name, successor)
        distance[h], choices[h], counts[h] = best, choice, count
    root = g.model.root
    witness, h = [], root
    if distance[root] is not None and distance[root] < 0:
        while choices[h] is not None:
            a, successor = choices[h]
            witness.append([h, a, successor])
            if successor is None:
                break
            h = successor
    certificate = {'model_hash': g.model.hash, 'evidence_hash': digest({j: str(rat(x)) for j, x in wealth.items()}),
                   'alpha': str(alpha), 'lower': {h: None if x is None else str(x)
                                               for h, x in distance.items()}}
    return {'current_pass': distance[root] is None or distance[root] >= 0,
            'root_residual': distance[root], 'unresolved_path': witness,
            'first_bad_paths': counts[root], 'relaxations': operations,
            'certificate': certificate}
