"""AH004-GRAPH-E-v1: frozen affine-box graph compiler, exact arithmetic.

Graph completeness relative to the real system and measurement authenticity are
external assumptions. Nodes are observable histories or justified tied suffixes,
NOT an arbitrary hidden-state aggregation. Every listed successor has positive,
parameter-independent support. No code is executed from input data.
"""
from dataclasses import dataclass, asdict
from fractions import Fraction as Q
from hashlib import sha256
import json
import re


def rat(x):
    if isinstance(x, bool) or not isinstance(x, (int, str, Q)):
        raise ValueError('Use exact integers, rational strings or Fraction')
    return Q(x)


def digest(x):
    return sha256(json.dumps(x, default=str, sort_keys=True,
                             separators=(',', ':')).encode()).hexdigest()


def ident(x):
    if not isinstance(x, str) or not re.fullmatch(r'[A-Za-z0-9_-]+', x):
        raise ValueError('Invalid identifier')
    return x


@dataclass(frozen=True)
class Action:
    name: str
    base: str
    bit: int
    keep: bool
    c: Q
    v: tuple
    next: tuple


@dataclass(frozen=True)
class Node:
    name: str
    actions: tuple


@dataclass(frozen=True)
class Model:
    root: str
    target: str
    eta: Q
    box: tuple
    nodes: tuple

    @property
    def hash(self):
        return digest(asdict(self))


@dataclass(frozen=True)
class Row:
    name: str
    offset: Q
    vector: tuple
    lo: Q
    hi: Q
    threshold: Q


@dataclass(frozen=True)
class Compiled:
    model: Model
    order: tuple
    rows: tuple
    terms: tuple
    blocked: tuple
    height: int
    max_terms: int


def parse(raw, max_nodes=10000):
    root, target, eta = ident(raw['root']), raw['target'], rat(raw['eta'])
    if target not in ('A', 'B', 'AB') or eta < 0:
        raise ValueError('Invalid target or tolerance')
    box = tuple((rat(a), rat(b)) for a, b in raw['box'])
    if any(a > b for a, b in box):
        raise ValueError('EMPTY parameter box; never vacuous SAFE')
    if not 0 < len(raw['nodes']) <= max_nodes:
        raise ValueError('Missing graph or node resource limit')
    nodes = []
    for n in raw['nodes']:
        actions = []
        for a in n['actions']:
            if type(a['bit']) is not int or a['bit'] not in (0, 1) or type(a['keep']) is not bool:
                raise ValueError('Invalid permission/channel attributes')
            v = tuple(map(rat, a['v']))
            nxt = tuple(ident(s) for s in a['next'])
            if len(v) != len(box) or len(set(nxt)) != len(nxt):
                raise ValueError('Dimension or duplicate successor')
            actions.append(Action(ident(a['name']), ident(a['base']), a['bit'],
                                  a['keep'], rat(a['c']), v, nxt))
        if len({a.name for a in actions}) != len(actions):
            raise ValueError('Duplicate action name')
        bases = {}
        for a in actions:
            bases.setdefault(a.base, []).append(a)
        for pair in bases.values():
            if len(pair) != 2 or {a.bit for a in pair} != {0, 1} or len({a.keep for a in pair}) != 1:
                raise ValueError('Every base needs both bits with identical channel classification')
        nodes.append(Node(ident(n['name']), tuple(actions)))
    if len({n.name for n in nodes}) != len(nodes) or root not in {n.name for n in nodes}:
        raise ValueError('Duplicate node or missing root')
    m = Model(root, target, eta, box, tuple(nodes))
    topology(m)  # Reject cycles and dangling edges, including dominated ones.
    return m


def topology(m):
    names = {n.name for n in m.nodes}
    edges = {n.name: {s for a in n.actions for s in a.next} for n in m.nodes}
    if any(s not in names for values in edges.values() for s in values):
        raise ValueError('Dangling successor')
    degree = dict.fromkeys(names, 0)
    for values in edges.values():
        for s in values:
            degree[s] += 1
    ready = sorted(n for n in names if degree[n] == 0)
    order = []
    while ready:
        h = ready.pop()
        order.append(h)
        for s in sorted(edges[h]):
            degree[s] -= 1
            if degree[s] == 0:
                ready.append(s)
    if len(order) != len(names):
        raise ValueError('Cyclic graph: unroll the finite observable history first')
    return tuple(order)


```
